async def handle_leave(self, ws):
        """Handle the player leaving the solo session."""
        if ws is not self.player:
            return

        if self.status == "playing":
            # Player left mid-game — end the session (no DB write for incomplete)
            self.status = "finished"
            self.active_tile = -1
            if self._countdown_task and not self._countdown_task.done():
                self._countdown_task.cancel()
        elif self.status in ("waiting", "countdown"):
            if self._countdown_task and not self._countdown_task.done():
                self._countdown_task.cancel()
            self.status = "finished"

        if self._rematch_timeout_task and not self._rematch_timeout_task.done():
            self._rematch_timeout_task.cancel()

        self.player = None

