func tileStyle(index, activeTile, flashTile, shakeTile int, flashProgress, shakeProgress float64) lipgloss.Style {
	col := index % 3
	base := lipgloss.NewStyle().
		Foreground(tileColors[col]).
		Align(lipgloss.Center).
		Padding(1, 2)

	if index == activeTile {
		base = base.Reverse(true)
	}

	// Flash (correct tap): subtle green tint, fades quickly
	if index == flashTile && flashProgress > 0 {
		base = base.Foreground(success).Bold(true)
	}

	// Shake (wrong tap): subtle red tint, fades quickly
	if index == shakeTile && shakeProgress > 0 {
		base = base.Foreground(errorC).Bold(true)
	}

	return base
}

func TestFingerprintURLEncoding(t *testing.T) {
	tests := []struct {
		name        string
		fingerprint string
	}{
		{
			name:        "fingerprint_with_slash",
			fingerprint: "SHA256:v/e3SjZ8crx8ifF/nr8QD8NY4T3pZlFjL7T5yQ9kLnA",
		},
		{
			name:        "fingerprint_without_slash",
			fingerprint: "SHA256:vMMFys+qX8R/e9KalFb8FRekGutwSlRg+yq9+kBWq9w",
		},
		{
			name:        "fingerprint_with_multiple_slashes",
			fingerprint: "SHA256:a/b/c/d/e/f",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			encoded := url.PathEscape(tt.fingerprint)
			// The encoded form must not contain unencoded slashes
			// (all '/' must be '%2F')
			if strings.Contains(encoded, "/") {
				t.Errorf("encoded fingerprint contains unencoded slash: %s", encoded)
			}
			// Decoding must round-trip back to the original
			decoded, err := url.PathUnescape(encoded)
			if err != nil {
				t.Fatalf("decode error: %v", err)
			}
			if decoded != tt.fingerprint {
				t.Errorf("round-trip mismatch: got %q, want %q", decoded, tt.fingerprint)
			}
		})
	}
}

async def handle_create_session(request: web.Request) -> web.Response:
    """POST /api/auth/session — mint JWT for user_id. Requires TUI service token.

    Called by the TUI after wish verifies SSH key possession.
    The service token is a shared secret in env vars, not a user JWT.
    """
    service_token = request.headers.get("X-Service-Token", "")
    if not service_token or not Config.TUI_SERVICE_TOKEN:
        return web.json_response({"error": "Service token required"}, status=401)
    if not _secrets.compare_digest(service_token, Config.TUI_SERVICE_TOKEN):
        return web.json_response({"error": "Invalid service token"}, status=403)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)

