func makePublicKeyAuth(cfg SSHServerConfig) ssh.PublicKeyHandler {
	client := &http.Client{Timeout: 10 * time.Second}

	return func(ctx ssh.Context, key ssh.PublicKey) bool {
		fp := gossh.FingerprintSHA256(key)
		ctx.SetValue(ctxKeyFingerprint, fp)

		// Try to look up existing user by fingerprint
		userID, found, err := lookupSSHKey(client, cfg.BackendURL, fp)
		if err != nil {
			log.Printf("ssh-key lookup error for %s: %v", fp, err)
			return false
		}

		var jwt string
		if found {
			// Known key — mint JWT via service token
			jwt, err = mintSessionJWT(client, cfg.BackendURL, cfg.ServiceToken, userID)
			if err != nil {
				log.Printf("session mint error for user %s: %v", userID, err)
				return false
			}
		} else {
			// Unknown key — create guest, then link SSH key
			jwt, userID, err = createGuestAndLinkKey(client, cfg.BackendURL, fp, key)
			if err != nil {
				log.Printf("guest creation error for %s: %v", fp, err)
				return false
			}
		}

		ctx.SetValue(ctxKeyJWT, jwt)
		ctx.SetValue(ctxKeyUserID, userID)
		log.Printf("SSH auth success: fp=%s user=%s", fp, userID)
		return true
	}
}

