	// 1. Create guest
	resp, err := client.Post(backendURL+"/api/auth/guest", "application/json", nil)
	if err != nil {
		return "", "", fmt.Errorf("guest: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != 200 {
		body, _ := io.ReadAll(resp.Body)
		return "", "", fmt.Errorf("guest: status %d: %s", resp.StatusCode, body)
	}

	var guest struct {
		Token  string `json:"token"`
		UserID string `json:"userId"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&guest); err != nil {
		return "", "", fmt.Errorf("guest decode: %w", err)
	}

	// 2. Link SSH key to the new guest account
	pubKeyStr := fmt.Sprintf("%s %s", key.Type(), base64.StdEncoding.EncodeToString(key.Marshal()))
	linkBody, _ := json.Marshal(map[string]string{"public_key": pubKeyStr, "label": "ssh"})
	req, err := http.NewRequest("POST", backendURL+"/api/auth/ssh-key", bytes.NewReader(linkBody))
	if err != nil {
		return "", "", err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+guest.Token)

	linkResp, err := client.Do(req)
	if err != nil {
		return guest.Token, guest.UserID, fmt.Errorf("link key: %w", err)
	}
	linkResp.Body.Close()

	if linkResp.StatusCode != 200 && linkResp.StatusCode != 201 {
