"""Shared decorators for HTTP handlers."""

from functools import wraps

from aiohttp import web

from backend.keys import USER


def require_auth(handler):
    """Decorator for endpoints that require authentication.

    Returns 401 if no user is attached to the request. Use this instead
    of inline `if not user: return 401` checks to make the auth requirement
    explicit and impossible to forget.
    """
    @wraps(handler)
    async def wrapper(request: web.Request) -> web.Response:
        user = request[USER]
        if not user:
            return web.json_response(
                {"error": "Authentication required"},
                status=401,
            )
        return await handler(request)
    return wrapper

func TestFingerprintInURLPath(t *testing.T) {
	fp := "SHA256:v/e3SjZ8crx8ifF/nr8QD8NY4T3pZlFjL7T5yQ9kLnA"
	backendURL := "http://localhost:8099"
	reqURL := backendURL + "/api/auth/ssh-key/" + url.PathEscape(fp)

