	}
}

async def handle_create_session(request: web.Request) -> web.Response:
    """POST /api/auth/session — mint JWT for user_id. Requires TUI service token.

    Called by the TUI after wish verifies SSH key possession.
    The service token is a shared secret in env vars, not a user JWT.
    """
    service_token = request.headers.get("X-Service-Token", "")
    if not service_token or not Config.TUI_SERVICE_TOKEN:
        return web.json_response({"error": "Service token required"}, status=401)
    if not _secrets.compare_digest(service_token, Config.TUI_SERVICE_TOKEN):
        return web.json_response({"error": "Invalid service token"}, status=403)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    if not isinstance(body, dict):
        return web.json_response({"error": "Request body must be a JSON object"}, status=400)

    user_id = body.get("user_id")
    if not isinstance(user_id, str) or not user_id:
        return web.json_response({"error": "user_id is required"}, status=400)

    conn = request.app[DB_CONN]
    user = get_user_by_id(conn, user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)

    token = create_jwt(user["id"], user["username"], is_guest=bool(user["is_guest"]))
    return web.json_response({"jwt": token})

